package com.ventas.service;
import com.ventas.dto.RoleModels.*;import com.ventas.dto.UserAdminModels.Permission;import com.ventas.repository.*;import com.ventas.security.AuthModels.Identity;import com.ventas.security.AuthFailure;import com.fasterxml.jackson.databind.ObjectMapper;import java.time.*;import java.util.*;import org.junit.jupiter.api.*;import static org.assertj.core.api.Assertions.*;import static org.mockito.Mockito.*;
class RolePermissionServiceTest{
 RolePermissionRepository repo=mock(RolePermissionRepository.class);RolePermissionService service=new RolePermissionService(repo,mock(UserAdminRepository.class),mock(BusinessTransactions.class),mock(org.springframework.transaction.support.TransactionTemplate.class),new ObjectMapper().findAndRegisterModules());String v="a".repeat(64);
 Editor editor(String code,boolean editable){return new Editor(2,code,"Rol","","A",editable,v,List.of(new Permission("INI.VER","INI","Inicio"),new Permission("SEG.PERFIL","SEG","Perfil"),new Permission("VEN.VENDER","VEN","Venta"),new Permission("VEN.COPIAR","VEN","Copiar"),new Permission("PRO.VER","PRO","Producto"),new Permission("CAJ.OPERAR","CAJ","Caja"),new Permission("REP.VENTAS","REP","Reporte")),List.of("INI.VER","SEG.PERFIL"),List.of("INI.VER","SEG.PERFIL"),0);}
 @Test void administratorCannotBeEdited(){assertThatThrownBy(()->service.validate(editor("ADM",false),new Change(v,List.of("INI.VER","SEG.PERFIL")))).isInstanceOf(AuthFailure.class).hasMessageContaining("protegidos");}
 @Test void staleVersionIsRejected(){assertThatThrownBy(()->service.validate(editor("VEN",true),new Change("b".repeat(64),List.of("INI.VER","SEG.PERFIL")))).isInstanceOf(AuthFailure.class).hasMessageContaining("Recarga");}
 @Test void essentialProfilePermissionsCannotBeRemoved(){assertThatThrownBy(()->service.validate(editor("VEN",true),new Change(v,List.of("INI.VER")))).isInstanceOf(AuthFailure.class);}
 @Test void financialPermissionCannotBeGrantedToSales(){assertThatThrownBy(()->service.validate(editor("VEN",true),new Change(v,List.of("INI.VER","SEG.PERFIL","REP.VENTAS")))).isInstanceOf(AuthFailure.class);}
 @Test void duplicatedPermissionsAreRejected(){assertThatThrownBy(()->service.validate(editor("VEN",true),new Change(v,List.of("INI.VER","INI.VER","SEG.PERFIL")))).isInstanceOf(AuthFailure.class);}
 @Test void dependenciesAreEnforced(){assertThatThrownBy(()->service.validate(editor("VEN",true),new Change(v,List.of("INI.VER","SEG.PERFIL","VEN.VENDER")))).isInstanceOf(AuthFailure.class).hasMessageContaining("requiere");}
 @Test void consistentSalesPermissionsAreAccepted(){assertThatCode(()->service.validate(editor("VEN",true),new Change(v,List.of("INI.VER","SEG.PERFIL","VEN.VENDER","PRO.VER","CAJ.OPERAR")))).doesNotThrowAnyException();}
 @Test void nonAdministratorCannotEvenReadEditor(){var actor=new Identity(1,"test","N","A","VEN",false,Set.of("SEG.PERMISOS"),UUID.randomUUID(),OffsetDateTime.now().plusHours(1));assertThatThrownBy(()->service.get(actor,2)).isInstanceOf(AuthFailure.class);verifyNoInteractions(repo);}
 @Test void versionChangesWhenAssignmentsChange(){var role=new RolePermissionRepository.Role(2,"VEN","Ventas","Desc","A",LocalDateTime.of(2026,10,25,10,0));assertThat(service.version(role,List.of(),List.of("INI.VER"))).isNotEqualTo(service.version(role,List.of(),List.of("INI.VER","SEG.PERFIL")));}
 @Test void reservedXmlCannotBeNewlyAssigned(){assertThatThrownBy(()->service.validate(editor("VEN",true),new Change(v,List.of("INI.VER","SEG.PERFIL","VEN.XML")))).isInstanceOf(AuthFailure.class).hasMessageContaining("XML");}
}
